public class AreaCalculator {
    private List<Object> shapes;

    public AreaCalculator(List<Object> shapes) {
        this.shapes = shapes;
    }

    public double sum() {
        double totalArea = 0;

        for (Object shape : shapes) {
            if (shape instanceof Square) {
                Square square = (Square) shape;
                totalArea += Math.pow(square.getLength(), 2);
            } else if (shape instanceof Circle) {
                Circle circle = (Circle) shape;
                totalArea += Math.PI * Math.pow(circle.getRadius(), 2);
            }
        }

        return totalArea;
    }
}

public class Main {
  public static void main(String[] args) {
    List<Object> shapes = new ArrayList<>();
    shapes.add(new Circle(2));
    shapes.add(new Square(5));
    shapes.add(new Square(6));

    AreaCalculator calculator = new AreaCalculator(shapes);
    SumCalculator sumCalculator = new SumCalculator(calculator);
    System.out.println(sumCalculator.toHTML());
  }
}

